": "Língua Portuguesa", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05LP23", "name": "Comparar informações apresentadas em gráficos ou tabelas", "description": "Comparar informações apresentadas em gráficos ou tabelas. Desenvolver atividades e/ou sequências didáticas que propiciem condições favoráveis para que os estudantes realizem a interpretação dos dados de gráficos, tabelas e outros recursos que compõem, sobretudo, os textos do campo de estudo e pesquisa.", "grade_level": "5º Ano", "competency": "Língua Portuguesa", "subject": "Língua Portuguesa", "axis": "ENSINO FUNDAMENTAL"}, {"code": "EF05LP24", "name": "Planejar e produzir texto sobre tema de interesse, organizando resultados de pesquisa em…", "description": "Planejar e produzir texto sobre tema de interesse, organizando resultados de pesquisa em fontes de informação impressas ou digitais, incluindo imagens e gráficos ou tabelas, considerando a situação comunicativa e o tema/assunto do texto.", "grade_level": "5º Ano", "competency": "Língua Portuguesa", "subject": "Língua Portuguesa", "axis": "ENSINO FUNDAMENTAL"}, {"code": "EF05LP25", "name": "Representar cenas de textos dramáticos, reproduzindo as falas das personagens, de acordo…", "description": "Representar cenas de textos dramáticos, reproduzindo as falas das personagens, de acordo com as rubricas de interpretação e movimento indicadas pelo autor.", "grade_level": "5º Ano", "competency": "Língua Portuguesa", "subject": "Língua Portuguesa", "axis": "ENSINO FUNDAMENTAL"}, {"code": "EF05LP26", "name": "Utilizar, ao produzir o texto, conhecimentos linguísticos e gramaticais: regras…", "description": "Utilizar, ao produzir o texto, conhecimentos linguísticos e gramaticais: regras sintáticas de concordância nominal e verbal, convenções de escrita de citações, pontuação Utilizar conhecimentos linguísticos e gramaticais ao produzir textos, aplicando regras sintáticas de concordância nominal e verbal, convenções para citações, pontuação correta (ponto final, dois- -pontos, vírgulas em enumerações) (ponto final, dois-pontos, vírgulas em enumerações) e regras ortográficas e normas ortográficas.", "grade_level": "5º Ano", "competency": "Língua Portuguesa", "subject": "Língua Portuguesa", "axis": "ENSINO FUNDAMENTAL"}, {"code": "EF05LP27", "name": "Utilizar, ao produzir o texto, recursos de Utilizar recursos de coesão pronominal, como…", "description": "Utilizar, ao produzir o texto, recursos de Utilizar recursos de coesão pronominal, como pronomes anafóricos, e coesão pronominal (pronomes anafóricos) e articuladores de relações de sentido (tempo, causa, oposição, conclusão, comparação), com nível adequado de informatividade.", "grade_level": "5º Ano", "competency": "Língua Portuguesa", "subject": "Língua Portuguesa", "axis": "ENSINO FUNDAMENTAL"}, {"code": "EF05MA01", "name": "Ler, escrever e ordenar números naturais até a ordem das centenas de milhar com…", "description": "Ler, escrever e ordenar números naturais até a ordem das centenas de milhar com compreensão das principais características do sistema de numeração decimal.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA02", "name": "Ler, escrever e ordenar números racionais na forma decimal com compreensão das principais…", "description": "Ler, escrever e ordenar números racionais na forma decimal com compreensão das principais características do sistema de numeração decimal, utilizando, como recursos, a composição e decomposição e a reta numérica.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA03", "name": "Identificar e representar frações (menores e maiores que a unidade), associando-as ao…", "description": "Identificar e representar frações (menores e maiores que a unidade), associando-as ao resultado de uma divisão ou Ler, escrever, comparar e representar números racionais nas formas decimal e fracionária na reta numérica; multiplicar número natural por fração e multiplicar fração por fração; resolver situações-problema envolvendo adição, subtração e multiplicação de à ideia de parte de um todo, utilizando a reta numérica como recurso.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA04", "name": "Identificar frações equivalentes", "description": "Identificar frações equivalentes. Comparar e ordenar números racionais nas formas decimal e fracionária com denominadores iguais.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA05", "name": "Comparar e ordenar números racionais positivos (representações fracionária e decimal),…", "description": "Comparar e ordenar números racionais positivos (representações fracionária e decimal), relacionando-os a pontos na reta numérica.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA06", "name": "Associar as representações 10%, 25%, 50%, 75% e 100% respectivamente à décima parte,…", "description": "Associar as representações 10%, 25%, 50%, 75% e 100% respectivamente à décima parte, quarta parte, metade, três quartos e um inteiro, para calcular porcentagens, utilizando estratégias pessoais, cálculo mental e Reconhecer que a porcentagem pode ser escrita na forma fracionária e/ou decimal.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA07", "name": "Resolver e elaborar problemas de adição e subtração com números naturais e com números…", "description": "Resolver e elaborar problemas de adição e subtração com números naturais e com números racionais, cuja representação decimal seja finita, utilizando estratégias diversas, como cálculo por estimativa, cálculo mental e algoritmos.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA08", "name": "Resolver e elaborar problemas de multiplicação e divisão com números naturais e com…", "description": "Resolver e elaborar problemas de multiplicação e divisão com números naturais e com números racionais cuja representação decimal é finita (com multiplicador natural é divisor natural e diferente de zero), utilizando estratégias diversas, como cálculo por estimativa, cálculo mental e algoritmos.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA09", "name": "Resolver e elaborar problemas simples de contagem envolvendo o princípio multiplicativo,…", "description": "Resolver e elaborar problemas simples de contagem envolvendo o princípio multiplicativo, como a determinação do número de agrupamentos possíveis ao combinar cada elemento de uma coleção com todos os elementos de outra coleção, por meio de diagramas de árvore ou por tabelas.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA10", "name": "Concluir, por meio de investigações, que a relação de igualdade existente entre dois…", "description": "Concluir, por meio de investigações, que a relação de igualdade existente entre dois membros permanece ao adicionar, subtrair, multiplicar ou dividir cada um desses membros por um mesmo número, para construir a noção de equivalência.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA12", "name": "Resolver problemas que envolvam variação de proporcionalidade direta entre duas…", "description": "Resolver problemas que envolvam variação de proporcionalidade direta entre duas Compreender o conceito de proporcionalidade direta; utilizar o conceito de proporcionalidade direta para resolver problemas envolvendo escalas de mapas; utilizar o padrão e regularidade todo em duas partes proporcionais grandezas, para associar a quantidade de um produto ao valor a pagar, alterar as quantidades de ingredientes de receitas, ampliar ou reduzir escala em mapas, entre outros.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA13", "name": "Resolver problemas envolvendo a partilha de uma quantidade em duas partes desiguais, tais…", "description": "Resolver problemas envolvendo a partilha de uma quantidade em duas partes desiguais, tais como dividir uma quantidade em duas partes, de modo que uma seja o dobro da outra, com compreensão da ideia de razão entre as partes e delas com o todo.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA14", "name": "Utilizar e compreender diferentes representações para a localização de objetos no plano,…", "description": "Utilizar e compreender diferentes representações para a localização de objetos no plano, como mapas, células em planilhas eletrônicas e coordenadas geográficas, a fim de desenvolver as primeiras noções de coordenadas cartesianas.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA15", "name": "Interpretar, descrever e representar a localização ou movimentação de objetos no plano…", "description": "Interpretar, descrever e representar a localização ou movimentação de objetos no plano cartesiano (1º quadrante), utilizando coordenadas cartesianas, indicando mudanças de direção e de sentido e giros.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA16", "name": "Associar figuras espaciais a suas planificações (prismas, pirâmides, cilindros e cones) e…", "description": "Associar figuras espaciais a suas planificações (prismas, pirâmides, cilindros e cones) e analisar, nomear e comparar seus atributos.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA17", "name": "Reconhecer, nomear e comparar polígonos, considerando lados, vértices e ângulos, e…", "description": "Reconhecer, nomear e comparar polígonos, considerando lados, vértices e ângulos, e desenhá-los, Conhecer as figuras geométricas planas: características, representações e ângulos dos triângulos e quadriláteros; definir ângulos formados pelo encontro das retas concorrentes; classificar os ângulos; utilizar o transferidor para utilizando material de desenho ou tecnologias digitais traçar ângulo e medir ângulos nos polígonos; classificar os triângulos e quadriláteros por meio dos lados e ângulos; classificar triângulos e quadriláteros, utilizando material concreto; compor e decompor figuras geométricas planas quanto aos lados e ângulos; identificar o eixo simétrico em figuras planas.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA18", "name": "Reconhecer a congruência dos ângulos e a proporcionalidade entre os lados correspondentes…", "description": "Reconhecer a congruência dos ângulos e a proporcionalidade entre os lados correspondentes de figuras poligonais em situações de ampliação e de redução em malhas quadriculadas e usando tecnologias digitais.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA19", "name": "Resolver e elaborar problemas envolvendo medidas das grandezas comprimento, área, massa,…", "description": "Resolver e elaborar problemas envolvendo medidas das grandezas comprimento, área, massa, tempo, temperatura e capacidade, recorrendo a transformações entre as unidades mais usuais em contextos socioculturais.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA20", "name": "Concluir, por meio de investigações, que figuras de perímetros iguais podem ter áreas…", "description": "Concluir, por meio de investigações, que figuras de perímetros iguais podem ter áreas diferentes e que, também, figuras que têm a mesma área podem ter perímetros diferentes.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA21", "name": "Noção de volume", "description": "Reconhecer volume como grandeza associada a sólidos geométricos e medir volumes por meio de empilhamento de cubos, utilizando, preferencialmente, objetos concretos.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA22", "name": "Apresentar todos os possíveis resultados de um Ampliar a ideia de espaço amostral por…", "description": "Apresentar todos os possíveis resultados de um Ampliar a ideia de espaço amostral por meio de experimento aleatório; determinar o espaço amostral de um experimento; experimento aleatório, estimando se esses resultados são igualmente prováveis ou não.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA23", "name": "Determinar a probabilidade de ocorrência de um resultado em eventos aleatórios, quando…", "description": "Determinar a probabilidade de ocorrência de um resultado em eventos aleatórios, quando todos os resultados possíveis têm a mesma chance de ocorrer (equiprováveis).", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA24", "name": "Interpretar dados estatísticos apresentados em textos, tabelas e gráficos (colunas ou…", "description": "Interpretar dados estatísticos apresentados em textos, tabelas e gráficos (colunas ou linhas), referentes a outras áreas do conhecimento ou a outros contextos, como saúde e trânsito, e produzir textos com o objetivo de sintetizar conclusões.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF05MA25", "name": "Realizar pesquisa envolvendo variáveis categóricas e numéricas, Ler e interpretar dados…", "description": "Realizar pesquisa envolvendo variáveis categóricas e numéricas, Ler e interpretar dados apresentados de maneira organizada por meio de listas, tabelas, diagramas gráficos; coletar e organizar dados em listas, tabelas, diagratabelas de dupla entrada, gráfico de colunas agrupadas, gráficos pictóricos e gráfico de linhas organizar dados coletados por meio de tabelas, gráficos de colunas, pictóricos e de linhas, com e sem uso de tecnologias digitais, e apresentar texto escrito sobre a finalidade da pesquisa e a síntese dos resultados.", "grade_level": "5º Ano", "competency": "Matemática", "subject": "Matemática", "axis": "DE ROTAÇÃO AO"}, {"code": "EF06CI01", "name": "Classificar como homogênea ou heterogênea a mistura de dois ou mais materiais (água e…", "description": "Classificar como homogênea ou heterogênea a mistura de dois ou mais materiais (água e sal, água e óleo, água, areia etc.).", "grade_level": "6º Ano", "competency": "Ciências", "subject": "Ciências", "axis": "CONHE-"}, {"code": "EF06CI02", "name": "Identificar evidências de transformações químicas a partir do resultado de misturas de…", "description": "Identificar evidências de transformações químicas a partir do resultado de misturas de materiais que originam produtos diferentes dos que foram misturados (mistura de ingredientes para fazer um bolo, mistura de vinagre com bicarbonato de sódio etc.).", "grade_level": "6º Ano", "competency": "Ciências", "subject": "Ciências", "axis": "CONHE-"}, {"code": "EF06CI03", "name": "Selecionar métodos mais adequados para a separação de diferentes sistemas heterogêneos a…", "description": "Selecionar métodos mais adequados para a separação de diferentes sistemas heterogêneos a partir da identificação de processos de separação de materiais (como a produção de sal de cozinha, a destilação de petróleo, entre outros).", "grade_level": "6º Ano", "competency": "Ciências", "subject": "Ciências", "axis": "CONHE-"}, {"code": "EF06CI04", "name": "Associar a produção de medicamentos e outros materiais sintéticos ao desenvolvimento…", "description": "Associar a produção de medicamentos e outros materiais sintéticos ao desenvolvimento científico e tecnológico, reconhecendo benefícios e avaliando impactos socioambientais.", "grade_level": "6º Ano", "competency": "Ciências", "subject": "Ciências", "axis": "CONHE-"}, {"code": "EF06CI05", "name": "Explicar a organização básica das células e seu papel como unidade estrutural e funcional…", "description": "Explicar a organização básica das células e seu papel como unidade estrutural e funcional dos seres vivos. Utilizar modelos, vídeos, observações no microscópio e a produção de materiais didáticos com massa de modelar ou outros recursos manuais para explorar a estrutura das células, destacando seus principais componentes e funções.", "grade_level": "6º Ano", "competency": "Ciências", "subject": "Ciências", "axis": "CONHE-"}, {"code": "EF06CI06", "name": "Concluir, com base na análise de ilustrações e/ou modelos (físicos ou digitais), que os…", "description": "Concluir, com base na análise de ilustrações e/ou modelos (físicos ou digitais), que os organismos são um complexo arranjo de sistemas com diferentes níveis de organização Analisar ilustrações, modelos físicos ou digitais que representem a organização dos seres vivos, destacando a hierarquia entre células, tecidos, órgãos, sistemas e organismo.", "grade_level": "6º Ano", "competency": "Ciências", "subject": "Ciências", "axis": "CONHE-"}, {"code": "EF06CI07", "name": "Justificar o papel do sistema nervoso na coordenação das ações motoras e sensoriais do…", "description": "Justificar o papel do sistema nervoso na coordenação das ações motoras e sensoriais do corpo, com base Utilizar modelos, vídeos e esquemas para apresentar as principais estruturas do sistema nervoso e suas funções, relacionando-as à coordenação das ações moto- Lentes corretivas na análise de suas estruturas básicas e respectivas funções.", "grade_level": "6º Ano", "competency": "Ciências", "subject": "Ciências", "axis": "CONHE-"}, {"code": "EF06CI08", "name": "Explicar a importância da visão (captação e interpretação das imagens) na interação do…", "description": "Explicar a importância da visão (captação e interpretação das imagens) na interação do organismo com o meio e, com base no funcionamento do olho humano, selecionar lentes adequadas para a correção de diferentes defeitos da visão.", "grade_level": "6º Ano", "competency": "Ciências", "subject": "Ciências", "axis": "CONHE-"}, {"code": "EF06CI09", "name": "Deduzir que a estrutura, a sustentação e a movimentação dos animais resultam da interação…", "description": "Deduzir que a estrutura, a sustentação e a movimentação dos animais resultam da interação entre os sistemas muscular, ósseo e nervoso.", "grade_level": "6º Ano", "competency": "Ciências", "subject": "Ciências", "axis": "CONHE-"}, {"code": "EF06CI10", "name": "Explicar como o funcionamento do sistema nervoso pode ser afetado por substâncias…", "description": "Explicar como o funcionamento do sistema nervoso pode ser afetado por substâncias psicoativas Promover discussões, apresentar vídeos, realizar rodas de conversa, dramatizações e utilizar metodologias como estudo de casos, debates, simulações e produção de campanhas educativas.", "grade_level": "6º Ano", "competency": "Ciências", "subject": "Ciências", "axis": "CONHE-"}]$json$::jsonb)
    AS x(code text,name text,description text,grade_level text,competency text,subject text,axis text)
)
INSERT INTO skills (code,name,description,grade_level,competency,subject,axis,municipality_id)
SELECT d.code,d.name,d.description,d.grade_level,d.competency,d.subject,d.axis,(SELECT id FROM muni)
FROM data d
ON CONFLICT (code, municipality_id) DO UPDATE SET
  name=EXCLUDED.name, description=EXCLUDED.description, grade_level=EXCLUDED.grade_level,
  competency=EXCLUDED.competency, subject=EXCLUDED.subject, axis=EXCLUDED.axis;
